questionvariables.text:
col(v) := matrix([v[1]],[v[2]]);
/* Design: sort vectors as same direction, opposite or not parallel; fixed category order. Entries 3 and 7 share a with different vectors. Source: adapted from SMP AS/A2 Core 4, Chapter 9, Exercise B, Q5. */
L: [[[3,2],[["opp",[-6,-4]],["not",[-1,-2]],["not",[6,5]],["same",[9,6]]]],[[3,-1],[["same",[9,-3]],["not",[-8,3]],["opp",[-9,3]],["not",[9,-2]]]],[[-3,2],[["not",[9,-5]],["opp",[3,-2]],["same",[-9,6]],["not",[-8,6]]]],[[-2,-4],[["not",[0,-2]],["opp",[1,2]],["same",[-6,-12]],["same",[-4,-8]]]],[[5,-2],[["not",[-5,3]],["opp",[-5,2]],["same",[10,-4]],["opp",[-15,6]]]],[[2,5],[["same",[6,15]],["same",[4,10]],["not",[-4,-9]],["opp",[-2,-5]]]],[[-3,2],[["same",[-9,6]],["not",[2,-2]],["opp",[3,-2]],["opp",[9,-6]]]],[[-4,-1],[["same",[-8,-2]],["not",[14,3]],["opp",[8,2]],["opp",[4,1]]]],[[-2,-1],[["opp",[2,1]],["same",[-6,-3]],["not",[3,2]],["opp",[4,2]]]],[[1,-3],[["same",[2,-6]],["not",[-3,4]],["same",[3,-9]],["opp",[-1,3]]]]];
ix: 1+rand(10);
av: L[ix][1];
/* category code: 1 same, 2 opp, 3 not; named error dg: same -> opp, opp -> same, not -> same; third option th: same -> not, opp -> not, not -> opp */
cc(s) := if s="same" then 1 elseif s="opp" then 2 else 3;
dgof: [2,1,1]; thof: [3,3,2];
cat1: cc(L[ix][2][1][1]); w1: L[ix][2][1][2];
r11: w1[1]/av[1]; r12: w1[2]/av[2]; kv1: r11;
opt1: [["same1", is(cat1=1), "same direction as a"], ["opp1", is(cat1=2), "opposite direction to a"], ["not1", is(cat1=3), "not parallel to a"]];
ta1: first(mcq_correct(opt1)); dg1: opt1[dgof[cat1]][1]; th1: opt1[thof[cat1]][1];
cat2: cc(L[ix][2][2][1]); w2: L[ix][2][2][2];
r21: w2[1]/av[1]; r22: w2[2]/av[2]; kv2: r21;
opt2: [["same2", is(cat2=1), "same direction as a"], ["opp2", is(cat2=2), "opposite direction to a"], ["not2", is(cat2=3), "not parallel to a"]];
ta2: first(mcq_correct(opt2)); dg2: opt2[dgof[cat2]][1]; th2: opt2[thof[cat2]][1];
cat3: cc(L[ix][2][3][1]); w3: L[ix][2][3][2];
r31: w3[1]/av[1]; r32: w3[2]/av[2]; kv3: r31;
opt3: [["same3", is(cat3=1), "same direction as a"], ["opp3", is(cat3=2), "opposite direction to a"], ["not3", is(cat3=3), "not parallel to a"]];
ta3: first(mcq_correct(opt3)); dg3: opt3[dgof[cat3]][1]; th3: opt3[thof[cat3]][1];
cat4: cc(L[ix][2][4][1]); w4: L[ix][2][4][2];
r41: w4[1]/av[1]; r42: w4[2]/av[2]; kv4: r41;
opt4: [["same4", is(cat4=1), "same direction as a"], ["opp4", is(cat4=2), "opposite direction to a"], ["not4", is(cat4=3), "not parallel to a"]];
ta4: first(mcq_correct(opt4)); dg4: opt4[dgof[cat4]][1]; th4: opt4[thof[cat4]][1];
cs: [cat1, cat2, cat3, cat4];
